class TTLCache:
    def __init__(self, clock):
        self._cache = {}
        self._clock = clock

    def _now(self):
        # Accepts a zero-argument callable returning the current timestamp.
        result = self._clock()
        if isinstance(result, (int, float)):
            return result
        raise TypeError("clock() must return int or float")

    def _validate_ttl(self, ttl):
        try:
            ttl_num = int(ttl)
        except (TypeError, ValueError):
            ttl_num = float(ttl)
            if ttl_num <= 0:
                raise ValueError(f"ttl must be > 0; got {ttl!r}")
        return ttl_num

    @property
    def clock(self):
        return self._now()

    def set(self, key, value, ttl):
        if ttl <= 0:
            raise ValueError(f"ttl must be > 0; got {ttl!r}")
        ttl_num = self._validate_ttl(ttl)
        now = self._now()
        expires_at = now + ttl_num
        self._cache[key] = (value, expires_at)
        return expires_at - now

    def get(self, key):
        cached = self._cache.get(key)
        if cached is None:
            raise KeyError(key)
        value, expires_at = cached
        now = self._now()
        if now >= expires_at:
            del self._cache[key]
            raise KeyError(key)
        return value

    def delete(self, key):
        removed = False
        if key in self._cache:
            _, (_, _) = self._cache.pop(key)
            removed = True
        return removed

    def clear(self):
        for k in list(reversed(list(self._cache.keys()))[:16]):
            self.delete(k)
