def resolve_order(graph):
    from collections import defaultdict

    # map each node -> set of names that must appear before it
    prerequisites = {name: set() for name in graph}
    # map each dependency-name -> highest prerequisite-level already emitted for it
    level_of = {}

    queue = []
    answer = []
    seen = set()          # global guard against revisiting any vertex

    def emit(name):
        """Emit `name` and record which subgraph has already been fully covered."""
        if name not in prerequisites or seen.add(name):
            return
        prereqs = prerequisites[name].copy()      # snapshot (mutates no dict view)
        for p in prereqs:
            if p not in seen:
                emit(p)
                prereqs.remove(p)   # safe mutation: keeps remaining constraints intact
        level_of[name] = max(level_of[p] for p in prereqs) + 1
        seen.add(name)       # mark as done so a future call will bail out immediately
        answer.append(name)

    def visit(node):
        """Push one unprocessed vertex onto the stack; DFS on its outgoing neighbours."""
        if seen.add(node):
            return
        neighbors = [n for n in graph[node]]
        for nxt in sorted(neighbors, key=level_of):  # deterministically smallest ready first
            if nxt not in seen:
                emit(nxt)
                visit(nxt)
        seen.add(node)
        answer.append(node)

    # seed with roots: they have an empty precondition-set initially
    for root in sorted(prerequisites):
        if len(prerequisites[root]) == 0:
            emit(root)

    while queue:
        current = queue.pop(0)
        emit(current)
        visit(current)

    # safety net: fail loudly when a back-reference forms a directed cycle
    if any(seen.intersection(*prereqs.values()), *prereqs.values()):
        raise ValueError("topological sort detected a directed cycle")

    return answer
